<template><section class="card-message-pending answer-pending" aria-busy="true"><div class="pending-copy" role="status"><span class="pending-mark" aria-hidden="true">✦</span><div><strong>正在编排回答</strong><p>内容逐步到达，卡片准备好后会直接显示</p></div></div><div class="pending-canvas" aria-hidden="true"><div class="pending-row"><i/><span/></div><div class="pending-line"/><div class="pending-line short"/><div class="pending-tiles"><b/><b/></div><div class="pending-mask"/></div><div class="pending-track" role="progressbar" aria-label="正在生成卡片" aria-valuetext="等待完整内容，无预估百分比"><span/></div></section></template>
<style scoped>.answer-pending{position:relative;border:1px solid var(--nx-border);border-radius:18px;background:var(--nx-surface);padding:18px;margin:12px 0;overflow:hidden;max-width:720px}.pending-copy{display:flex;align-items:center;gap:11px;position:relative;z-index:1}.pending-mark{color:var(--nx-accent);font-size:23px}.pending-copy strong{font-size:13px;font-weight:600;color:var(--nx-text)}.pending-copy p{font-size:11px;line-height:1.6;color:var(--nx-text-2);margin:4px 0 0}.pending-canvas{position:relative;height:142px;padding:18px 2px 12px;overflow:hidden;opacity:.75}.pending-row{display:flex;gap:10px;align-items:center;margin-bottom:13px}.pending-row i{width:29px;height:29px;border-radius:9px;background:var(--nx-accent-soft)}.pending-row span{width:38%;height:10px}.pending-row span,.pending-line,.pending-tiles b{display:block;border-radius:5px;background:var(--nx-surface-3,var(--nx-border))}.pending-line{height:7px;margin:11px 0;width:89%}.pending-line.short{width:67%}.pending-tiles{display:flex;gap:12px;margin-top:16px}.pending-tiles b{height:33px;flex:1;border-radius:9px;background:var(--nx-surface-2)}.pending-mask{position:absolute;inset:-30% -90%;background:linear-gradient(110deg,transparent 35%,var(--nx-surface) 48%,var(--nx-accent-soft) 52%,transparent 65%);filter:blur(14px);opacity:.65;animation:pending-wash 2.6s ease-in-out infinite}.pending-track{height:3px;background:var(--nx-border);border-radius:4px;overflow:hidden}.pending-track span{display:block;width:38%;height:100%;border-radius:4px;background:var(--nx-accent);opacity:.7;animation:pending-scan 2.3s cubic-bezier(.4,0,.2,1) infinite}@keyframes pending-wash{0%{transform:translateX(-26%)}100%{transform:translateX(26%)}}@keyframes pending-scan{0%{transform:translateX(-100%)}100%{transform:translateX(360%)}}@media(prefers-reduced-motion:reduce){.pending-mask,.pending-track span{animation:none}.pending-mask{opacity:.2}.pending-track span{width:100%;opacity:.3}}@media(max-width:600px){.answer-pending{